#include "AutoEq.h"
#include <algorithm>
#include <cmath>
#include <complex>
#include <numeric>
namespace vocal {namespace {
constexpr int rate=24000,nfft=2048,hop=1024;
void fft(std::array<std::complex<double>,nfft>& a){for(int i=1,j=0;i<nfft;++i){int b=nfft>>1;for(;j&b;b>>=1)j^=b;j^=b;if(i<j)std::swap(a[i],a[j]);}for(int len=2;len<=nfft;len<<=1){const auto w=std::polar(1.0,-2*pi/len);for(int i=0;i<nfft;i+=len){std::complex<double> phase=1;for(int j=0;j<len/2;++j){auto x=a[i+j],y=a[i+j+len/2]*phase;a[i+j]=x+y;a[i+j+len/2]=x-y;phase*=w;}}}}
double rms(const std::vector<float>& audio,const EqSettings& eq){VocalParameters p;p.inputDb=eq.inputDb;p.highPassHz=eq.highPass;p.warmthDb=eq.warmth;p.presenceDb=eq.presence;p.deharsh=eq.deharsh;p.deEss=eq.deEss;p.thresholdDb=0;p.ratio=1;p.makeupDb=0;p.reverb=p.delay=0;VocalChain chain;chain.prepare(rate);chain.setParameters(p);double power=0;for(float v:audio){float l=v,r=v;chain.processDry(l,r);power+=static_cast<double>(l)*l;}return std::sqrt(power/std::max<std::size_t>(1,audio.size()));}
}
bool EqSettings::valid() const noexcept{return std::isfinite(highPass)&&highPass>=40&&highPass<=180&&std::isfinite(warmth)&&warmth>=-8&&warmth<=6&&std::isfinite(presence)&&presence>=-6&&presence<=8&&std::isfinite(deharsh)&&deharsh>=0&&deharsh<=1&&std::isfinite(deEss)&&deEss>=0&&deEss<=1&&std::isfinite(inputDb)&&inputDb>=-24&&inputDb<=12;}
bool sameEq(const EqSettings& a,const EqSettings& b) noexcept{return std::abs(a.highPass-b.highPass)<.001&&std::abs(a.warmth-b.warmth)<.001&&std::abs(a.presence-b.presence)<.001&&std::abs(a.deharsh-b.deharsh)<.001&&std::abs(a.deEss-b.deEss)<.001&&std::abs(a.inputDb-b.inputDb)<.001;}
EqRecommendation recommendEq(const AudioChannels& input,double sourceRate,const EqSettings& before,std::atomic<bool>& cancel,std::atomic<float>& progress){EqRecommendation result;auto fail=[&](const char* text){result.message=text;return result;};if(!before.valid()||input.empty()||input.size()>2||!std::isfinite(sourceRate)||sourceRate<16000||sourceRate>192000||input[0].size()<sourceRate*5)return fail("Cần ít nhất 5 giây micro khô ở sample rate từ 16 kHz; hát nhiều câu thấp/cao, không dùng beat.");for(const auto& c:input)if(c.size()!=input[0].size())return fail("Các kênh âm thanh không cùng độ dài.");
    // At most twelve five-second excerpts distributed over the entire song.
    std::vector<float> mono;const auto segment=static_cast<std::size_t>(sourceRate*5);const int count=static_cast<int>(std::min<std::size_t>(12,input[0].size()/segment));std::size_t clipped=0,total=0;mono.reserve(segment*count);
    int strongest=0;if(input.size()==2){double a=0,b=0;for(std::size_t i=0;i<input[0].size();i+=32){a+=input[0][i]*input[0][i];b+=input[1][i]*input[1][i];}strongest=b>a?1:0;}
    for(int s=0;s<count;++s){if(cancel)return fail("Đã hủy phân tích, EQ cũ được giữ nguyên.");const auto start=count==1?0:static_cast<std::size_t>((input[0].size()-segment)*static_cast<double>(s)/(count-1));for(std::size_t i=0;i<segment;++i){const float sample=input[strongest][start+i];if(!std::isfinite(sample))return fail("Bản thu có mẫu âm thanh không hợp lệ.");if(std::abs(sample)>=.999f)++clipped;mono.push_back(sample);++total;}}
    result.clippedFraction=static_cast<double>(clipped)/std::max<std::size_t>(1,total);if(result.clippedFraction>.003)return fail("Micro bị clip nhiều: giảm gain vật lý trên UPod Pro rồi thu lại. EQ không sửa được âm đã vỡ.");auto reduced=resampleBandlimited(mono.data(),mono.size(),sourceRate,rate);mono.clear();progress=.1f;AudioChannels voice{reduced};std::atomic<float> pitchProgress{0};auto pitch=analysePitch(voice,rate,true,cancel,pitchProgress);if(cancel)return fail("Đã hủy phân tích, EQ cũ được giữ nguyên.");result.voicedSeconds=pitch.voicedFraction*reduced.size()/rate;if(result.voicedSeconds<3||pitch.voicedFraction<.12)return fail("Chưa có đủ giọng hát rõ. Dùng micro khô, Mixing OFF, hát ít nhất vài câu và tránh nhiễu lớn.");progress=.55f;
    std::vector<double> notes;for(const auto& frame:pitch.frames)if(frame.confidence>=.8)notes.push_back(frame.midi);std::sort(notes.begin(),notes.end());if(notes[notes.size()*9/10]-notes[notes.size()/10]<2)return fail("Mẫu chỉ có một cao độ hoặc tiếng ù đều. Hát vài câu có cả nốt thấp và cao trước khi cân EQ.");const double lowHz=440*std::pow(2,(notes[notes.size()/10]-69)/12);
    std::array<double,6> energy{};int frames=0;std::array<std::complex<double>,nfft> spectrum{};constexpr double edges[7]={20,80,180,450,1800,5500,10000};
    for(std::size_t offset=0;offset+nfft<=reduced.size();offset+=hop){if(cancel)return fail("Đã hủy phân tích, EQ cũ được giữ nguyên.");const double seconds=(offset+nfft*.5)/rate;auto at=std::lower_bound(pitch.frames.begin(),pitch.frames.end(),seconds-.10,[](const PitchFrame& a,double s){return a.seconds<s;});bool voiced=false;for(;at!=pitch.frames.end()&&at->seconds<seconds+.10;++at)if(at->confidence>=.8&&at->rms>.003){voiced=true;break;}if(!voiced)continue;double power=0;for(int i=0;i<nfft;++i){const double v=reduced[offset+i];power+=v*v;spectrum[i]=v*(.5-.5*std::cos(2*pi*i/(nfft-1)));}if(power/nfft<1e-6)continue;fft(spectrum);std::array<double,6> bands{};for(int bin=2;bin<nfft/2;++bin){const double hz=static_cast<double>(bin)*rate/nfft;for(int b=0;b<6;++b)if(hz>=edges[b]&&hz<edges[b+1]){bands[b]+=std::norm(spectrum[bin]);break;}}const double sum=std::accumulate(bands.begin(),bands.end(),0.0);if(sum<=1e-14)continue;for(int b=0;b<6;++b)energy[b]+=bands[b]/sum;++frames;progress=.55f+.3f*static_cast<float>(offset)/reduced.size();}
    if(frames<30)return fail("Không đủ đoạn giọng sạch để đề xuất EQ.");for(int b=0;b<6;++b)result.bandDb[b]=10*std::log10(std::max(1e-10,energy[b]/frames));const double mid=std::max(1e-10,energy[3]),body=10*std::log10(std::max(1e-10,energy[2])/mid),bright=10*std::log10(std::max(1e-10,energy[4])/mid),ess=10*std::log10(std::max(1e-10,energy[5])/mid);
    auto& eq=result.suggested;eq.highPass=static_cast<float>(std::clamp(lowHz*.45,40.0,90.0));eq.warmth=static_cast<float>(std::clamp(-(body-3)*.25,-3.0,1.0));eq.presence=static_cast<float>(std::clamp(-(bright+12)*.18,-3.0,1.5));eq.deharsh=static_cast<float>(std::clamp((bright+8)*.035,0.0,.5));eq.deEss=static_cast<float>(std::clamp(.2+(ess+24)*.025,.15,.65));eq.inputDb=before.inputDb;
    const double oldRms=rms(reduced,before),newRms=rms(reduced,eq);result.matchDb=std::clamp(20*std::log10(std::max(1e-12,oldRms)/std::max(1e-12,newRms)),-3.0,3.0);eq.inputDb=std::clamp(before.inputDb+static_cast<float>(result.matchDb),-24.0f,12.0f);if(cancel)return fail("Đã hủy phân tích, EQ cũ được giữ nguyên.");result.valid=eq.valid();result.message="Đề xuất nhẹ từ các đoạn giọng rõ; nghe A/B trước khi lưu. Không đổi nốt, không tự tăng bass cho mọi nốt trầm. Bù mức A/B là ước tính, không phải loudness chuẩn phát hành.";if(result.clippedFraction>0)result.message+=" Có đỉnh clip: giảm gain vật lý nếu giọng còn méo.";progress=1;return result;
}
}
